sh -c 'echo "#smoke-host 1"; echo "#os-release"; grep -E "^(ID|VERSION_ID|VERSION_CODENAME)=" /etc/os-release; echo "#kernel"; uname -r; echo "#packages dpkg"; dpkg-query -W -f="\${db:Status-Abbrev}\t\${Package}\t\${Version}\t\${Architecture}\t\${source:Package}\t\${source:Version}\n"; echo "#services"; systemctl list-units --type=service --state=running --no-legend --plain 2>/dev/null | cut -d" " -f1; echo "#reboot-required"; [ -f /var/run/reboot-required ] && echo yes || echo no' > smoke-host.txt && echo "Saved $(pwd)/smoke-host.txt"
